import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        while ((line = br.readLine()) != null && !line.isEmpty()) {
            String[] parts = line.trim().split("\\s+");
            if (parts.length == 0) continue;

            int[] sequence = new int[parts.length];
            for (int i = 0; i < parts.length; i++) {
                sequence[i] = Integer.parseInt(parts[i]);
            }

            // Build the graph
            Map<Integer, TreeSet<Integer>> graph = new HashMap<>();
            Stack<Integer> path = new Stack<>();

            // Start from room 1
            path.push(1);
            graph.put(1, new TreeSet<>());

            for (int i = 0; i < sequence.length; i++) {
                int currentRoom = sequence[i];

                if (currentRoom == 0) {
                    // Going back to previous room
                    if (path.size() > 1) {
                        path.pop();
                    }
                } else {
                    // Moving to a new room or existing room
                    int previousRoom = path.peek();

                    // Add edges between previous and current room
                    graph.computeIfAbsent(previousRoom, k -> new TreeSet<>()).add(currentRoom);
                    graph.computeIfAbsent(currentRoom, k -> new TreeSet<>()).add(previousRoom);

                    // Push current room onto path
                    path.push(currentRoom);
                }
            }

            // Output the graph
            List<Integer> sortedRooms = new ArrayList<>(graph.keySet());
            Collections.sort(sortedRooms);

            StringBuilder sb = new StringBuilder();
            for (int room : sortedRooms) {
                sb.append(room);
                for (int neighbor : graph.get(room)) {
                    sb.append(" ").append(neighbor);
                }
                sb.append("\n");
            }
            System.out.print(sb.toString());

            // Check if there's more input
            if (br.ready()) {
                System.out.println();
            }
        }
    }
}

