public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        int test = 1;
        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }

            if (n == 0) break;

            List<Integer> seq = new ArrayList<>();
            seq.add(n);
            while (true) {
                int x = fs.nextInt();
                if (x == 0) break;
                seq.add(x);
            }

            int maxRoom = 0;
            for (int x : seq) maxRoom = Math.max(maxRoom, x);

            List<TreeSet<Integer>> adj = new ArrayList<>();
            for (int i = 0; i <= maxRoom; i++) adj.add(new TreeSet<>());

            for (int i = 1; i < seq.size(); i++) {
                int u = seq.get(i - 1);
                int v = seq.get(i);
                if (u != v) {
                    adj.get(u).add(v);
                    adj.get(v).add(u);
                }
            }

            out.append("Case ").append(test++).append(":\n");
            for (int i = 1; i <= maxRoom; i++) {
                out.append(i).append(" ->");
                for (int v : adj.get(i)) {
                    out.append(' ').append(v);
                }
                out.append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

