// Structure for adjacency list node
typedef struct AdjListNode {
    int dest;
    struct AdjListNode* next;
} AdjListNode;

// Structure for adjacency list
typedef struct AdjList {
    AdjListNode* head;
} AdjList;

// Graph structure
typedef struct Graph {
    int V;
    AdjList* array;
} Graph;

// Function to create a new adjacency list node
AdjListNode* newAdjListNode(int dest) {
    AdjListNode* newNode = (AdjListNode*)malloc(sizeof(AdjListNode));
    newNode->dest = dest;
    newNode->next = NULL;
    return newNode;
}

// Function to create a graph with V vertices
Graph* createGraph(int V) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->V = V;
    graph->array = (AdjList*)malloc(V * sizeof(AdjList));
    for (int i = 0; i < V; ++i)
        graph->array[i].head = NULL;
    return graph;
}

// Function to add an edge to an undirected graph
void addEdge(Graph* graph, int src, int dest) {
    AdjListNode* newNode = newAdjListNode(dest);
    newNode->next = graph->array[src].head;
    graph->array[src].head = newNode;

    newNode = newAdjListNode(src);
    newNode->next = graph->array[dest].head;
    graph->array[dest].head = newNode;
}

// Function to compare two integers for qsort
int compare(const void* a, const void* b) {
    return (*(int*)a - *(int*)b);
}

// Function to print the adjacency list of the graph
void printGraph(Graph* graph) {
    for (int v = 0; v < graph->V; v++) {
        // Count neighbors
        int count = 0;
        AdjListNode* crawl = graph->array[v].head;
        while (crawl) {
            count++;
            crawl = crawl->next;
        }

        // Store neighbors in array
        int* neighbors = (int*)malloc(count * sizeof(int));
        int idx = 0;
        crawl = graph->array[v].head;
        while (crawl) {
            neighbors[idx++] = crawl->dest;
            crawl = crawl->next;
        }

        // Sort neighbors
        qsort(neighbors, count, sizeof(int), compare);

        // Print room and its adjacent rooms
        printf("%d", v);
        for (int i = 0; i < count; i++) {
            printf(" %d", neighbors[i]);
        }
        printf("\n");

        free(neighbors);
    }
}

