#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *v;
    int sz;
    int cap;
} Vec;

static void vec_init(Vec *a) {
    a->v = NULL;
    a->sz = 0;
    a->cap = 0;
}

static void vec_push(Vec *a, int x) {
    if (a->sz == a->cap) {
        a->cap = (a->cap == 0 ? 4 : a->cap * 2);
        a->v = (int *)realloc(a->v, a->cap * sizeof(int));
    }
    a->v[a->sz++] = x;
}

static int cmp_int(const void *p1, const void *p2) {
    int a = *(const int *)p1;
    int b = *(const int *)p2;
    return (a > b) - (a < b);
}

int main(void) {
    int x;
    int maxRoom = 0;
    int cap = 1005;
    Vec *adj = (Vec *)malloc(cap * sizeof(Vec));
    for (int i = 0; i < cap; ++i) vec_init(&adj[i]);

    int prev = -1;
    int first = 1;

    while (scanf("%d", &x) == 1) {
        if (x == 0) break;

        if (x >= cap) {
            int old = cap;
            while (cap <= x) cap *= 2;
            adj = (Vec *)realloc(adj, cap * sizeof(Vec));
            for (int i = old; i < cap; ++i) vec_init(&adj[i]);
        }

        if (x > maxRoom) maxRoom = x;

        if (!first) {
            vec_push(&adj[prev], x);
            vec_push(&adj[x], prev);
        }
        prev = x;
        first = 0;
    }

    for (int i = 1; i <= maxRoom; ++i) {
        if (adj[i].sz > 0) {
            qsort(adj[i].v, adj[i].sz, sizeof(int), cmp_int);

            printf("%d:", i);
            int last = -1;
            for (int j = 0; j < adj[i].sz; ++j) {
                if (adj[i].v[j] != last) {
                    printf(" %d", adj[i].v[j]);
                    last = adj[i].v[j];
                }
            }
            printf("\n");
        }
    }

    for (int i = 0; i < cap; ++i) free(adj[i].v);
    free(adj);
    return 0;
}
